referenceSolutions.javascript:
export function solve(value) {
  const out = {};
  const walk = (x, path) => {
    if (x !== null && typeof x === "object" && !Array.isArray(x) && Object.keys(x).length) {
      for (const k of Object.keys(x)) walk(x[k], path ? path + "." + k : k);
    } else if (path) out[path] = x;
  };
  walk(value, "");
  return out;
}

referenceSolutions.typescript:
export function solve(value: Record<string, any>): any {
  const out: Record<string, any> = {};
  const walk = (x: any, path: string): void => {
    if (x !== null && typeof x === "object" && !Array.isArray(x) && Object.keys(x).length) {
      for (const k of Object.keys(x)) walk(x[k], path ? path + "." + k : k);
    } else if (path) out[path] = x;
  };
  walk(value, "");
  return out;
}
